// Resolve scanners based on profile
const input = $input.first().json;
const profile = input.body?.profile || 'standard';

const profiles = {
  quick: ['gitleaks', 'trivy'],
  standard: ['trivy', 'gitleaks', 'opengrep', 'checkov', 'grype', 'syft', 'detect-secrets'],
  comprehensive: ['opengrep', 'bandit', 'gosec', 'eslint-security', 'pmd', 'nuclei', 'trivy', 'grype', 'gitleaks', 'detect-secrets', 'checkov', 'syft', 'cosign', 'opa', 'conftest']
};

const requestedScanners = input.body?.scanners;
const scanners = requestedScanners?.length > 0 ? requestedScanners : (profiles[profile] || profiles.standard);

// Split into batches of 5 for parallel execution
const batchSize = 5;
const batches = [];
for (let i = 0; i < scanners.length; i += batchSize) {
  batches.push(scanners.slice(i, i + batchSize));
}

return batches.map((batch, idx) => ({
  json: {
    batchIndex: idx,
    scanners: batch,
    scanId: input.body?.scanId,
    projectId: input.body?.projectId,
    userId: input.body?.userId,
    profile,
    branch: input.body?.branch || 'main'
  }
}));

// Execute each scanner in the batch via backend API
const batch = $input.first().json;
const results = [];

for (const scanner of batch.scanners) {
  try {
    const response = await this.helpers.httpRequest({
      method: 'POST',
      url: `${process.env.BACKEND_URL || 'http://backend:4000'}/internal/scanners/execute`,
      headers: { 'X-Internal-API-Key': process.env.INTERNAL_API_KEY, 'Content-Type': 'application/json' },
      body: {
        scanId: batch.scanId,
        projectId: batch.projectId,
        userId: batch.userId,
        scanner,
        branch: batch.branch,
        profile: batch.profile
      },
      timeout: 300000
    });
    results.push(response);
  } catch (error) {
    results.push({ scanner, success: false, error: error.message, findings: [], duration: 0 });
  }
}

return [{ json: { batchIndex: batch.batchIndex, results, scanId: batch.scanId, projectId: batch.projectId } }];

// Aggregate all batch results
const allResults = [];
for (const item of $input.all()) {
  if (item.json.results) {
    allResults.push(...item.json.results);
  }
}

const scanId = $input.first().json.scanId;
const projectId = $input.first().json.projectId;

// Calculate totals
let totalFindings = { critical: 0, high: 0, medium: 0, low: 0, info: 0, total: 0 };
let totalDuration = 0;

for (const result of allResults) {
  totalDuration += result.duration || 0;
  for (const f of result.findings || []) {
    totalFindings[f.severity] = (totalFindings[f.severity] || 0) + 1;
    totalFindings.total++;
  }
}

return [{
  json: {
    scanId,
    projectId,
    results: allResults,
    totalFindings,
    totalDuration,
    scannersRun: allResults.length,
    successful: allResults.filter(r => r.success).length
  }
}];
